import redis.clients.jedis.HostAndPort;
import redis.clients.jedis.JedisCluster;
import redis.clients.jedis.JedisPoolConfig;
import java.util.HashSet;
import java.util.Set;

public class RedisClusterClientExample {
    public static void main(String[] args) {
        Set<HostAndPort> clusterNodes = new HashSet<>();
        clusterNodes.add(new HostAndPort("192.168.1.101", 6379));
        clusterNodes.add(new HostAndPort("192.168.1.102", 6379));
        clusterNodes.add(new HostAndPort("192.168.1.103", 6379));

        JedisPoolConfig poolConfig = new JedisPoolConfig();
        poolConfig.setMaxTotal(128);
        poolConfig.setMaxIdle(32);

        try (JedisCluster jedisCluster = new JedisCluster(clusterNodes, poolConfig)) {
            // Using hash tags to guarantee keys land on the same shard
            String userKey = "{user:42}:profile";
            String cartKey = "{user:42}:cart";

            jedisCluster.set(userKey, "{"name":"Alice"}");
            jedisCluster.hset(cartKey, "item_99", "2");

            System.out.println("User Profile: " + jedisCluster.get(userKey));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
